import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const node = new Group();

  // --- Plane with texture ----------------------------------------------------
  const geometry = new PlaneGeometry(7, 6);
  const material = new MeshBasicNodeMaterial({ map: null, transparent: true });
  const plane = new Mesh(geometry, material);
  node.add(plane);

  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // --- Text ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: (item.typography && item.typography.fontSize) || 31,
      color: (config.visual && config.visual.colors && config.visual.colors.paper) || '#e8ecf2',
      align: 'left',
    });
    // slightly in front of the plane
    txt.position.set(0, 0, 0.01);
    node.add(txt);
  }

  // --- UserData ------------------------------------------------------------
  node.userData.handlers = {};

  node.userData.cleanup = () => {
    // Dispose material, geometry and texture
    material.dispose && material.dispose();
    geometry.dispose && geometry.dispose();
    if (loadedTexture && loadedTexture.dispose) loadedTexture.dispose();

    // Kill any GSAP timelines that might have been created elsewhere
    if (node.userData._gsapTimelines) {
      for (const tl of node.userData._gsapTimelines) {
        tl.kill();
      }
    }
  };

  return node;
}
